import pytest
from app import normalize_optional_text
@pytest.mark.parametrize("value,expected", [(None,""),("",""),(" ",""),(" a ","a"),("你好","你好"),("\ta\n","a")])
def test_values(value, expected):
    assert normalize_optional_text(value) == expected
@pytest.mark.parametrize("value", [0,1,False,[],{},b"a"])
def test_wrong_types(value):
    with pytest.raises(TypeError):
        normalize_optional_text(value)

