import pytest
from app import parse_count
@pytest.mark.parametrize("text,default,expected", [("0",9,0),("+12",9,12),(" -5 ",7,-5),("bad",7,7),("",-3,-3),("1.5",None,None),("0x10",44,44),(" ",99,99)])
def test_parse(text, default, expected):
    assert parse_count(text, default) == expected
@pytest.mark.parametrize("value", [None,1,False,[],{}])
def test_wrong_types(value):
    with pytest.raises(TypeError):
        parse_count(value, 7)
